-- Reference migration for the two-phase decision log (`TomSqlDecisionLog`).
--
-- Creates `tom_transaction_decision`: one row per prepared branch of a
-- two-phase transaction that decided to commit, written before its commit
-- phase and deleted once every branch committed. `TomTransactionRecovery`
-- commits the prepared branches recorded here and rolls back the rest. This
-- file is the canonical DDL and is kept in sync with `decisionTable()` in
-- `lib/src/tomserver/transactions/transaction_recovery.dart`;
-- `test/framework_schema_test.dart` replays this chain and compares the schema
-- it builds against the descriptor, so the two cannot drift apart.
--
-- The table lives in a one-phase data source: a decision has to be durable on
-- its own before the first branch commits. Apply this file when the
-- application's database user is not permitted to run DDL, and configure the
-- log with `createSchema: false`.
CREATE TABLE IF NOT EXISTS tom_transaction_decision (
  transaction_id VARCHAR(64) NOT NULL,
  branch_id VARCHAR(200) NOT NULL,
  decided_at TIMESTAMP(6) NOT NULL,
  PRIMARY KEY (transaction_id, branch_id)
);
